{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx theme build",
    "description": "Compile standalone themes or one keyed theme family",
    "usage": "astryx theme build [options] <files...>",
    "options": [
      {
        "flags": "--family",
        "description": "Build the selected extension family into one keyed CSS, JS, and declaration set, written beside the family root theme file, which must be inside the working directory to build (ERR_PATH_TRAVERSAL); --check only reads, so it compares outputs anywhere. Requires --family-key; refused with --out or --watch (ERR_THEME_INVALID)"
      },
      {
        "flags": "--family-key <key>",
        "description": "Lower-kebab filename stem required with --family and refused without it; must differ from every member name (ERR_THEME_INVALID)"
      },
      {
        "flags": "-o, --out <path>",
        "description": "Output CSS file path, relative or absolute; the .js and .d.ts are written beside it (default: <theme name>.css next to the source). A build writes only inside the working directory, the defaults beside the source too (ERR_PATH_TRAVERSAL); --check writes nothing, so it compares outputs anywhere and refuses only a relative path that escapes the working directory. Single theme only: refused with more than one file or with --family (ERR_THEME_INVALID)"
      },
      {
        "flags": "--icons-specifier <specifier>",
        "description": "Override the icon-registry import in the generated JS module, for example ./icons.mjs (default: the specifier in the theme source's own import). With --family it applies to every member's icon import"
      },
      {
        "flags": "-w, --watch",
        "description": "Rebuild automatically when a theme file changes (Ctrl-C to stop). Refused with --check, --family, or --json (ERR_THEME_INVALID)"
      },
      {
        "flags": "-c, --check",
        "description": "Verify the committed outputs match the source without writing; exit non-zero if stale. Composes with --family and several files; refused with --watch (ERR_THEME_INVALID)"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
